/**
 * IdoSell auth helpers.
 *
 * IdoSell is not OAuth here: the per-shop Admin API key (`X-API-KEY` header)
 * is generated by the merchant in their panel and entered directly through
 * the Connect Link form (see `./connect-form.ts`). IdoSell also documents an
 * OAuth2 app-install flow and a legacy SHA1 date-signature scheme, but the
 * task scope for this adapter is the API-key path — the OAuth flow requires
 * a registered marketplace app + `apps.idosell.com` install callback that is
 * out of scope, and the legacy signature scheme is explicitly excluded.
 *
 * `getAuthUrl` / `exchangeCode` exist only to satisfy `BaseAdapter` (every
 * adapter must implement them); they are never reachable for an api_key
 * platform because the Connect page renders the credential form instead of
 * an OAuth redirect. Same shape as
 * `apps/integration-server/src/verticals/ecommerce/adapters/insales/auth.ts`.
 *
 * Docs: https://www.idosell.com/en/developers/,
 * https://idosell.readme.io/reference/productsproductsget (X-API-KEY / bearerAuth
 * security schemes, identical on every endpoint's OpenAPI fragment).
 */

import type { Credentials } from '@opensteward/shared'

/** Informational panel URL — there is no OAuth authorize redirect to build. */
export function buildAuthUrl(shopDomain: string): string {
  const host = shopDomain.replace(/^https?:\/\//, '').replace(/\/+$/, '')
  return `https://${host}/admin/`
}

export function exchangeCode(): Promise<Credentials> {
  throw new Error(
    'IdoSell does not use OAuth code exchange. Generate an Admin API key in the ' +
      "shop's panel and POST it to /v1/connections with body " +
      '`{ platform: "idosell", credentials: { apiKey, shopDomain } }`.',
  )
}
